import{_ as i,o as s,c as a,a3 as t}from"./chunks/framework.d6OaePA7.js";const g=JSON.parse('{"title":"家用摄像头本地存储和查看","description":"","frontmatter":{},"headers":[],"relativePath":"pages/explore/others/家用摄像头本地存储和查看.md","filePath":"pages/explore/others/家用摄像头本地存储和查看.md","lastUpdated":1693917276000}'),l={name:"pages/explore/others/家用摄像头本地存储和查看.md"};function o(r,e,n,d,p,h){return s(),a("div",null,[...e[0]||(e[0]=[t('<h1 id="家用摄像头本地存储和查看" tabindex="-1">家用摄像头本地存储和查看 <a class="header-anchor" href="#家用摄像头本地存储和查看" aria-label="Permalink to &quot;家用摄像头本地存储和查看&quot;">​</a></h1><blockquote><p>硬件: 支持ONVIF的家用摄像头, Tplink好像全系支持, 我用的型号是44gw</p><p>技术方案: Shinobi + alist + zertier/cloudflared</p></blockquote><p>最开始是在张大妈上看到有人用<code>nas</code> 实现摄像头的本地存储和查看, 因为威联通和群晖都有对应的套件支持, 可以流程式配置. 但是Linux版本没有对应的套件, 所以就只能自己搜索相关方案, 在接近眼瞎后终于搞好了.</p><p>第一个搜到的是<strong>ZoneMinder</strong>, 但是都说它性能不好, 继而诞生了<strong>Shinobi</strong>, 所以我的方案就一步到位, 直接使用<strong>Shinobi</strong>进行配置.</p><p>目前实现的功能有</p><ul><li>摄像头支持运动检测 (<strong>Shinobi</strong>)</li><li>检测到运动后进行视频保存 (<strong>Shinobi</strong>)</li><li>循环保存视频(3天内) (<strong>Shinobi</strong>)</li><li>可以通过alist进行视频网页查看 (<strong>alist</strong>)</li><li>如果本地没外网ip, 也可以进行外网访问查看视频 (<strong>cloudflared</strong>)</li></ul><h2 id="_1-shinobi配置" tabindex="-1">1. Shinobi配置 <a class="header-anchor" href="#_1-shinobi配置" aria-label="Permalink to &quot;1. Shinobi配置&quot;">​</a></h2><p>官网地址: <a href="https://docs.shinobi.video/" target="_blank" rel="noreferrer">https://docs.shinobi.video/</a></p><p>该说不说, Shinobi的网页看的眼睛是真累, 黑底白字, 还都是小小的英文, 眼睛都要瞎了.</p><h3 id="_1-安装shinobi" tabindex="-1">1. 安装Shinobi <a class="header-anchor" href="#_1-安装shinobi" aria-label="Permalink to &quot;1. 安装Shinobi&quot;">​</a></h3><p><img src="https://cdn.jsdelivr.net/gh/scattter/blogweb/images/image-20230221121709114.png" alt="image-20230221121709114"></p><p>这里官网推荐使用本地安装, 这样便于安装许多插件以及和主机交互. 但是由于我需求没那么多, 所以就使用docker安装了.</p><ul><li>安装命令</li></ul><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> bash</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &lt;(</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -s</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://gitlab.com/Shinobi-Systems/Shinobi-Installer/raw/master/shinobi-docker.sh)</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>运行该命令后会自动生成一个<code>docker-compose</code> 的启动文件, 里面有挂载地址和启动端口等, 如下</p><p><img src="https://cdn.jsdelivr.net/gh/scattter/blogweb/images/image-20230221121957674.png" alt="image-20230221121957674"></p><ul><li>访问页面</li></ul><p>在浏览器里面输入<code>ip+8080</code> 即可访问配置页面. 首次登录的时候(此时我们网址后面要加一个<code>/super</code> 后缀)需要使用超级管理员登录, 然后重建一个新用户. 创建成功后退出超级管理员页面, 然后使用新账户登录普通后台配置页(<code>ip+8080</code> ). 关于本流程官网描述如下</p><p><img src="https://cdn.jsdelivr.net/gh/scattter/blogweb/images/image-20230221122231864.png" alt="image-20230221122231864"></p><h3 id="_2-添加摄像头和监视器" tabindex="-1">2. 添加摄像头和监视器 <a class="header-anchor" href="#_2-添加摄像头和监视器" aria-label="Permalink to &quot;2. 添加摄像头和监视器&quot;">​</a></h3><p>如果你的摄像头支持<code>ONVIF</code> 协议, 那么就很容易添加.</p><ul><li>添加摄像头</li></ul><p>在上一步骤使用新建账户登录页面后, 在侧边栏找到<code>ONVIF Scanner</code> 选项, 点击后进入设备搜索添加页面. 在页面的<code>Scan Setting</code> 区域设置你摄像头的ip地址, 端口号, 用户名和登录密码, 以<code>Tplink</code> 为例, ip地址和端口信息可以在APP的<code>设备</code>页, 通过右上角<code>更多设置</code> -&gt; <code>我的摄像机</code>找到, 用户名和密码是APP上设置的账号密码. 当这些信息输入后即可点击下面的<code>Search</code> 按钮进行搜索.</p><p><img src="https://cdn.jsdelivr.net/gh/scattter/blogweb/images/image-20230221122605506.png" alt="image-20230221122605506"></p><p>如果上面设置无问题, 同时你的设备也没问题, 右侧便会检测到摄像头, 如下所示</p><p><img src="https://cdn.jsdelivr.net/gh/scattter/blogweb/images/image-20230221123248992.png" alt="image-20230221123248992"></p><p>如果按照上面操作没有找到相应摄像头, 那么可以用官网<code>Adding a Camera Manually</code> 章节的其他方法进行添加. 这里我没实际操作过, 就不进行扩展了.</p><ul><li>添加监视器</li></ul><p>在上一步骤成功添加摄像头后, 工具自动给我们添加一个监视器<code>Monitor</code>, 我们需要对这个监视器进行一些基本的操作.</p><ol><li>在左侧栏找到<code>Monitor Setting</code> 选项, 点击后在右侧页面选择我们刚才自动创建的监视器, 然后进行配置(如果不在右侧选择, 默认是新增加监视器). 确保其<code>Mode</code> 为<code>Watch-only</code> 模式, 在该模式下才能进行后续运动监测录制, 其他如<code>Record</code> 模式是24小时录制.</li></ol><p><img src="https://cdn.jsdelivr.net/gh/scattter/blogweb/images/image-20230221124138137.png" alt="image-20230221124138137"></p><ol start="2"><li>在页面右下角将当前设置改为高级设置, 如下所示.</li></ol><p><img src="https://cdn.jsdelivr.net/gh/scattter/blogweb/images/image-20230221150851433.png" alt="image-20230221150851433"></p><ol start="3"><li>在修改完毕后, 我们选择左侧的<code>Stream</code> 选项, 将右侧的<code>Stream Type</code> 暂时更改为<code>MJPEG</code> 模式, 这种模式便于我们通过实时h外面行运动检测的测试. (默认的<code>HLS</code> 不能在我们页面上实时显示摄像头画面, 但是其利于长时间运行的运动监测, 所以后续我们需要再调整过来.)</li></ol><p><img src="https://cdn.jsdelivr.net/gh/scattter/blogweb/images/image-20230221124558113.png" alt="image-20230221124558113"></p><ol start="4"><li>继续选择<code>Detector Settings</code> 选项, 将右侧的<code>Enabled</code> 更改为<code>Yes</code>, 如下所示.</li></ol><p><img src="https://cdn.jsdelivr.net/gh/scattter/blogweb/images/image-20230221124849369.png" alt="image-20230221124849369"></p><p>这里我们可以再去设置下监测区域, 这里直接鼠标拖动右侧红色区域的点即可</p><p><img src="https://cdn.jsdelivr.net/gh/scattter/blogweb/images/image-20230221134625279.png" alt="image-20230221134625279"></p><ol start="5"><li>随后点击右下角的保存按钮即可, 此时我们可以在<code>Live Grid</code> 选项里面看到摄像头的事实画面.</li><li>测试是否成功设置. 此时需要一个运动的物体进入摄像头区域, 然后再消失. 完成上面步骤后, 进入右侧菜单的<code>Videos</code> 页面, 刷新查看是否成功记录下来. 如果和下图一样有视频存在, 那就表示设置成功. 此时我们需要再返回步骤三, <strong>将右侧的<code>Stream Type</code> 暂时更改为<code>HLS</code> 模式</strong>.</li></ol><p><img src="https://cdn.jsdelivr.net/gh/scattter/blogweb/images/image-20230221125217801.png" alt="image-20230221125217801"></p><ol start="7"><li>保存后即配置完成.</li></ol><h2 id="_2-alist设置" tabindex="-1">2. Alist设置 <a class="header-anchor" href="#_2-alist设置" aria-label="Permalink to &quot;2. Alist设置&quot;">​</a></h2><p>这一步来说是比较简单的, 只需要运行对应容器即可, 需要注意的是这里宿主机挂载的地址在容器内<code>/opt/alist/data</code> 目录下, 即如果我们把宿主机的<code>/root</code> 挂在到容器上, 我们在挂载本地资源的时候根路径<code>/opt/alist/data</code> 就相当于宿主机的<code>/root</code> 目录.</p><p>启动命令可参考</p><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -d</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --restart=always</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -v</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /etc/alist:/opt/alist/data</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -p</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> 5244:5244</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -e</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> PUID=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">0</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -e</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> PGID=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">0</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -e</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> UMASK=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">022</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --name=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;alist&quot;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> xhofe/alist:latest</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>启动成功后, 即可将自己本地的监控录像地址挂载上去. 如下所示</p><p><img src="https://cdn.jsdelivr.net/gh/scattter/blogweb/images/image-20230221134859433.png" alt="image-20230221134859433"></p><h2 id="_3-zerotier-cloudflared设置" tabindex="-1">3. Zerotier/Cloudflared设置 <a class="header-anchor" href="#_3-zerotier-cloudflared设置" aria-label="Permalink to &quot;3. Zerotier/Cloudflared设置&quot;">​</a></h2><p>这里可以参考我之前的<a href="https://scattter.github.io/devops/others/%E7%89%A9%E7%90%86%E6%9C%BA%E5%AE%89%E8%A3%85Linux%E5%90%8C%E6%97%B6%E5%AE%9E%E7%8E%B0%E5%86%85%E7%BD%91%E7%A9%BF%E9%80%8F.html" target="_blank" rel="noreferrer">文章(点击即可进入)</a></p><p>Zerotier用于内网访问, Cloudflared用户外网访问. 设置好后即可访问.</p><p><img src="https://cdn.jsdelivr.net/gh/scattter/blogweb/images/image-20230221150214596.png" alt="image-20230221150214596"></p><h2 id="_4-最后" tabindex="-1">4. 最后 <a class="header-anchor" href="#_4-最后" aria-label="Permalink to &quot;4. 最后&quot;">​</a></h2><p>Shinobi支持的功能还有很多, 包括物体检测, 消息通知等, 以及还有许多插件, 但是目前我还用不到这些, 而且它的网页看着也就费眼, 这些就后面有兴趣了再去探索下.</p>',54)])])}const k=i(l,[["render",o]]);export{g as __pageData,k as default};
